contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _recipient) public {
        uint256 balBefore = address(c).balance;
        uint256 recipBefore = _recipient.balance;
        bool reverted;
        try c.withdrawAll(_recipient) { reverted = false; }
        catch { reverted = true; }
        uint256 balAfter = address(c).balance;
        if (reverted) {
            assert(balAfter == balBefore);
        } else {
            assert(balAfter == 0 && _recipient.balance == recipBefore + balBefore);
        }
    }
    receive() external payable {}
}

